-- DISABLED 2026-08-26 (uncategorized-bucket dedup): duplicate of the categorized
-- mart JUSTICE.JUSTICE__XC_UN_CONSOLIDATED_SANCTIONS_LIST (1,011 rows, 32 cols
-- vs 30). Built 2026-08-26 by the ID_HINTS fallback. On drop list.

-- Source: INTL_UN_CONSOLIDATED_SANCTIONS (1011 rows)
-- Generated by scripts/gen_mart_models.py
-- Fixed 2026-09-20: LAST_DAY_UPDATED/INDIVIDUAL_DATE_OF_BIRTH were bare
-- try_to_date() calls -- a pure-digit value would misread as epoch seconds
-- instead of failing safely. No staging model matches this source: the only
-- UN-sanctions staging model (models/staging/xc_un_consolidated_sanctions_list)
-- reads a DIFFERENT landing table (XC_UN_CONSOLIDATED_SANCTIONS_LIST, not
-- this INTL_-prefixed one), so wrapped the two bare casts in place. This
-- model stays disabled (drop-list duplicate, see above) -- fixed anyway since
-- it's a landmine either way.

with source as (
    select * from {{ source('ripple_raw', 'INTL_UN_CONSOLIDATED_SANCTIONS') }}
)

select
    DATAID as dataid,
    VERSIONNUM as versionnum,
    FIRST_NAME as first_name,
    SECOND_NAME as second_name,
    UN_LIST_TYPE as un_list_type,
    REFERENCE_NUMBER as reference_number,
    LISTED_ON as listed_on,
    GENDER as gender,
    COMMENTS1 as comments1,
    HAS_INTERPOL_LINK as has_interpol_link,
    INTERPOL_LINK as interpol_link,
    NATIONALITY as nationality,
    LIST_TYPE as list_type,
    {{ stg_date('LAST_DAY_UPDATED') }} as last_day_updated,
    INDIVIDUAL_ALIAS as individual_alias,
    INDIVIDUAL_ADDRESS as individual_address,
    {{ stg_date('INDIVIDUAL_DATE_OF_BIRTH') }} as individual_date_of_birth,
    INDIVIDUAL_PLACE_OF_BIRTH as individual_place_of_birth,
    INDIVIDUAL_DOCUMENT as individual_document,
    SORT_KEY as sort_key,
    SORT_KEY_LAST_MOD as sort_key_last_mod,
    RECORD_TYPE as record_type,
    DESIGNATION as designation,
    TITLE as title,
    THIRD_NAME as third_name,
    FOURTH_NAME as fourth_name,
    NAME_ORIGINAL_SCRIPT as name_original_script,
    LAST_REVIEWED_ON as last_reviewed_on,
    ENTITY_ALIAS as entity_alias,
    ENTITY_ADDRESS as entity_address
from source
